import{c as t,Q as a,j as o,m as r}from"./chunks/framework.W-g_WCNV.js";const u=JSON.parse('{"title":"Backups","description":"Encrypted database backups to local storage or any S3-compatible object store.","frontmatter":{"title":"Backups","description":"Encrypted database backups to local storage or any S3-compatible object store."},"headers":[],"relativePath":"admin/backups.md","filePath":"admin/backups.md"}'),s={name:"admin/backups.md"};function d(i,e,n,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r(`<p>GateKeeper stores all of its state - users, sessions, OIDC clients, groups, settings - in a single SQLite file. The Backups page lets you snapshot that file on demand or on a schedule, encrypt it, and store it locally or in the cloud.</p><p>Manage backups at <code>/admin/backups</code>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>GateKeeper uses SQLite&#39;s <code>VACUUM INTO</code> statement to create a consistent, read-consistent copy of the database without locking out normal operations.</li><li>The snapshot is encrypted with AES-256-GCM. The key is derived from your <code>SECRET_KEY</code> using SHA-256.</li><li>The encrypted file is uploaded to your configured storage backend.</li><li>A record is added to the backup history table so you can see, download, and restore past backups from the UI.</li></ol><p>Backups are named by timestamp: <code>gatekeeper-2025-01-15T14-30-00Z.db.enc</code>.</p><h2 id="storage-backends" tabindex="-1">Storage backends <a class="header-anchor" href="#storage-backends" aria-label="Permalink to &quot;Storage backends&quot;">​</a></h2><h3 id="local-filesystem" tabindex="-1">Local filesystem <a class="header-anchor" href="#local-filesystem" aria-label="Permalink to &quot;Local filesystem&quot;">​</a></h3><p>Writes the encrypted backup to a directory inside the container. To persist backups across container restarts, bind-mount a host directory to the path you configure:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/host/path/backups:/backups</span></span></code></pre></div><p>Then set the directory path to <code>/backups</code> in the UI.</p><h3 id="s3-compatible" tabindex="-1">S3-compatible <a class="header-anchor" href="#s3-compatible" aria-label="Permalink to &quot;S3-compatible&quot;">​</a></h3><p>Works with any S3-compatible object store:</p><table tabindex="0"><thead><tr><th>Provider</th><th>Notes</th></tr></thead><tbody><tr><td>AWS S3</td><td>Set region to your bucket&#39;s region. Path-style: No.</td></tr><tr><td>Cloudflare R2</td><td>Endpoint: <code>https://&lt;account-id&gt;.r2.cloudflarestorage.com</code>. Region: <code>auto</code>. Path-style: No.</td></tr><tr><td>Backblaze B2</td><td>Endpoint: <code>https://s3.&lt;region&gt;.backblazeb2.com</code>. Path-style: No.</td></tr><tr><td>MinIO</td><td>Use your MinIO endpoint. Path-style: Yes.</td></tr><tr><td>Garage</td><td>Use your Garage endpoint. Path-style: Yes.</td></tr></tbody></table><p><strong>Key prefix</strong> organises backup objects inside the bucket. The default <code>gatekeeper/</code> keeps backups in their own virtual folder.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Storage type</td><td><code>Disabled</code>, <code>Local filesystem</code>, or <code>S3-compatible</code>.</td></tr><tr><td>Directory path</td><td>(Local) Absolute path inside the container where backups are written.</td></tr><tr><td>Endpoint URL</td><td>(S3) Full URL of the S3 endpoint.</td></tr><tr><td>Bucket</td><td>(S3) Bucket name.</td></tr><tr><td>Region</td><td>(S3) AWS region or <code>auto</code> for Cloudflare R2.</td></tr><tr><td>Access key</td><td>(S3) S3 access key ID.</td></tr><tr><td>Secret key</td><td>(S3) S3 secret access key. Leave blank to keep the current value.</td></tr><tr><td>Key prefix</td><td>(S3) Object key prefix. Default: <code>gatekeeper/</code>.</td></tr><tr><td>Path-style addressing</td><td>(S3) Use <code>Yes</code> for self-hosted stores (MinIO, Garage). Use <code>No</code> for AWS, R2, B2.</td></tr><tr><td>Automatic backups</td><td>How often to run automatic backups: manual only, hourly, daily, or weekly.</td></tr><tr><td>Retention count</td><td>How many backups to keep. The oldest are deleted automatically when a new one is created.</td></tr></tbody></table><h2 id="running-a-backup" tabindex="-1">Running a backup <a class="header-anchor" href="#running-a-backup" aria-label="Permalink to &quot;Running a backup&quot;">​</a></h2><p>Click <strong>Back up now</strong> from the Backups page to create an immediate snapshot. The page reloads with the new backup in the history table.</p><h2 id="restoring-a-backup" tabindex="-1">Restoring a backup <a class="header-anchor" href="#restoring-a-backup" aria-label="Permalink to &quot;Restoring a backup&quot;">​</a></h2><p>Click <strong>Restore</strong> on any backup in the history table. GateKeeper will:</p><ol><li>Download the encrypted backup from storage.</li><li>Decrypt it using your <code>SECRET_KEY</code>.</li><li>Write the decrypted database to <code>&lt;db-path&gt;.restore</code> (e.g. <code>/data/gatekeeper.db.restore</code>).</li></ol><p>To complete the restore:</p><ol><li>Stop GateKeeper.</li><li>Rename <code>/data/gatekeeper.db</code> to <code>/data/gatekeeper.db.bak</code> (keep it as a safety copy).</li><li>Rename <code>/data/gatekeeper.db.restore</code> to <code>/data/gatekeeper.db</code>.</li><li>Start GateKeeper.</li></ol><p>All active sessions from the backup are restored. Sessions created after the backup was taken are lost.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You must use the same <code>SECRET_KEY</code> that was active when the backup was created. A different key cannot decrypt the backup.</p></div><h2 id="downloading-a-backup" tabindex="-1">Downloading a backup <a class="header-anchor" href="#downloading-a-backup" aria-label="Permalink to &quot;Downloading a backup&quot;">​</a></h2><p>Click <strong>Download</strong> on any backup to download the raw encrypted file to your browser. You can decrypt it offline with any AES-256-GCM implementation. The key is the SHA-256 hash of your <code>SECRET_KEY</code>.</p><h2 id="automatic-backups" tabindex="-1">Automatic backups <a class="header-anchor" href="#automatic-backups" aria-label="Permalink to &quot;Automatic backups&quot;">​</a></h2><p>Set <strong>Automatic backups</strong> to a schedule other than &quot;Manual only&quot;. The scheduler starts from GateKeeper&#39;s launch time - an hourly schedule creates a backup one hour after startup, then every hour after that.</p><p>Schedule changes take effect after the next restart.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p>The <strong>Retention count</strong> controls how many backups are kept per storage backend. When a new backup is created and the count exceeds the retention limit, the oldest backups are deleted from both the storage backend and the history table automatically.</p>`,32)])])}const b=t(s,[["render",d]]);export{u as __pageData,b as default};
